def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return min(float(budget), 35.0)

    active_bids = []
    cindy_bid = None
    eric_bid = None
    for agent_id, opp in opponents_status.items():
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if opp.get('alive') and bid is not None:
            active_bids.append(float(bid))
        if agent_id == 'Cindy' and opp.get('alive') and bid is not None:
            cindy_bid = float(bid)
        if agent_id == 'Eric' and opp.get('alive') and bid is not None:
            eric_bid = float(bid)

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    urgent = hp <= 4 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    base = 32.0

    if eric_bid is not None:
        base = max(base, min(eric_bid + 2.0, 86.0))
    elif active_bids:
        base = max(base, min(max(active_bids) + 1.5, 80.0))
    else:
        base = 49.0

    if cindy_bid is not None and cindy_bid >= 120.0 and not urgent:
        base = min(base, 74.0)

    if loose_supply and not urgent:
        base *= 0.78
    elif tight_supply:
        base *= 1.12

    if urgent:
        base = max(base, 78.0)
    if critical:
        base = max(base, 92.0)

    remaining_days = max(0, 10 - int(day) + 1)
    reserve_floor = max(0.0, remaining_days * 18.0)
    spend_cap = float(budget)
    if not urgent:
        spend_cap = max(0.0, float(budget) - reserve_floor)
        spend_cap = min(float(budget), max(28.0, spend_cap))

    bid = min(float(budget), min(spend_cap, base))

    if critical and budget > 0:
        bid = min(float(budget), max(bid, 95.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    if not alive_opps:
        return min(budget, int(DAILY_SALARY * 0.4))

    # Read yesterday bids from traces to infer pressure.
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', False):
            continue
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: with limited supply, bids that secure water matter more.
    # Our need is fixed at 9; if supply is near minimum, competition is higher.
    supply_norm = 0.0
    try:
        supply_norm = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
    except Exception:
        supply_norm = 0.0
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Base bid: mid fraction of salary, higher when supply is tight.
    tight_multiplier = 1.0 + (1.0 - supply_norm) * 0.35  # up to +35% when tight

    # If Cindy-type pressure existed (high previous max bid), raise bid to avoid being outcompeted.
    pressure_multiplier = 1.0
    if highest_prev_bid >= DAILY_SALARY * 0.8:
        pressure_multiplier = 1.25
    elif highest_prev_bid >= DAILY_SALARY * 0.4:
        pressure_multiplier = 1.10

    # HP critical: bid more to protect survival.
    if hp <= 1:
        hp_multiplier = 1.35
    elif hp <= 2:
        hp_multiplier = 1.25
    elif hp <= 3:
        hp_multiplier = 1.15
    else:
        hp_multiplier = 1.0

    target = int(DAILY_SALARY * 0.55 * tight_multiplier * pressure_multiplier * hp_multiplier)

    # If yesterday pressure was extremely high, try to slightly overmatch.
    if highest_prev_bid > 0:
        target = max(target, int(highest_prev_bid * 0.95))

    # Never exceed budget.
    if budget <= 0:
        return 0
    if target > budget:
        target = int(budget)

    # Keep at least a minimal nonzero bid when we have budget and hp is not safe.
    if target <= 0 and budget > 0 and hp <= 3:
        target = int(min(budget, DAILY_SALARY * 0.7))

    return int(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)
    else:
        bid = min(my_status['budget'], max(avg_prev * 1.05, 60.0))

    return float(bid)
